/**
 * Deadline Tracker — static deadline definitions (spec TASK-2).
 *
 * Per steering (deadline-tracker.md): CFR cites and official URLs are HARDCODED here,
 * never generated by the LLM. Each `calculate` is a pure function over the profile that
 * returns `Date | null` (null when a required source date is missing).
 */
import type { Profile } from "../api/profile";
import {
  asDate,
  gracePeriodEnd,
  h1bGracePeriodEnd,
  optDeadline,
  optWindowOpen,
  sevpDeadline,
  stemGracePeriodEnd,
  stemOptDeadline,
  stemOptWindowOpen,
} from "../utils/deadlineCalculations";

export type DeadlineId =
  | "opt_window_open"
  | "opt_deadline"
  | "ead_expiry"
  | "stem_window_open"
  | "stem_deadline"
  | "i20_expiry"
  | "grace_period_end"
  | "sevp_reporting"
  | "i94_expiry"
  | "h1b_petition_expiry"
  | "cap_gap_end"
  | "visa_stamp_expiry"
  | "passport_expiry"
  | "renewal_reminder";

export interface DeadlineDefinition {
  id: DeadlineId;
  label: string;
  description: string;
  consequence: string;
  regulationCite: string;
  officialUrl: string;
  applicableVisaTypes: string[];
  applicablePhases?: string[];
  /** The profile field that, when set, overrides the computed value (REQ-7). */
  overrideSourceField?: keyof Profile;
  calculate: (profile: Profile) => Date | null;
}

const USCIS_OPT = "https://www.uscis.gov/working-in-the-united-states/students-and-exchange-visitors/optional-practical-training-opt-for-f-1-students";
const USCIS_STEM = "https://www.uscis.gov/working-in-the-united-states/students-and-exchange-visitors/students-and-employment/stem-opt";
const SEVP_REPORTING = "https://studyinthestates.dhs.gov/students/maintaining-status";
const USCIS_H1B = "https://www.uscis.gov/working-in-the-united-states/h-1b-specialty-occupations";
const TRAVEL_DOCS = "https://travel.state.gov/content/travel/en/us-visas.html";

export const DEADLINE_DEFINITIONS: DeadlineDefinition[] = [
  {
    id: "opt_window_open",
    label: "OPT application window opens",
    description:
      "The earliest date you may file your post-completion OPT application (Form I-765). You can file up to 90 days before your program end date.",
    consequence:
      "Filing before the window opens means USCIS can reject the application outright.",
    regulationCite: "8 CFR 214.2(f)(11)(i)(A)",
    officialUrl: USCIS_OPT,
    applicableVisaTypes: ["F-1"],
    calculate: (p) => optWindowOpen(p.programEndDate),
  },
  {
    id: "opt_deadline",
    label: "OPT application deadline",
    description:
      "The latest date USCIS can receive your post-completion OPT application — no later than 60 days after your program end date, and it must be filed within 30 days of your DSO's recommendation.",
    consequence:
      "Missing this window means you lose the chance to apply for OPT for that program level.",
    regulationCite: "8 CFR 214.2(f)(11)(i)(B)",
    officialUrl: USCIS_OPT,
    applicableVisaTypes: ["F-1"],
    calculate: (p) => optDeadline(p.programEndDate),
  },
  {
    id: "ead_expiry",
    label: "EAD card expiry",
    description:
      "The expiration date on your Employment Authorization Document. You may not work past this date unless an extension is pending under the applicable rules.",
    consequence:
      "Working after your EAD expires is unauthorized employment and can jeopardize your status.",
    regulationCite: "8 CFR 274a.12(c)(3)",
    officialUrl: USCIS_OPT,
    applicableVisaTypes: ["OPT", "STEM_OPT"],
    overrideSourceField: "eadEndDate",
    calculate: (p) => asDate(p.eadEndDate),
  },
  {
    id: "stem_window_open",
    label: "STEM OPT filing window opens",
    description:
      "The earliest date you may file your 24-month STEM OPT extension — up to 90 days before your current OPT EAD expires.",
    consequence:
      "Filing before the window opens can lead to rejection; file within the window to stay covered.",
    regulationCite: "8 CFR 214.2(f)(11)(iii)",
    officialUrl: USCIS_STEM,
    applicableVisaTypes: ["OPT", "STEM_OPT"],
    calculate: (p) => stemOptWindowOpen(p.eadEndDate),
  },
  {
    id: "stem_deadline",
    label: "STEM OPT filing deadline",
    description:
      "The latest practical date to file your STEM OPT extension — about 60 days before your OPT EAD expires — so USCIS receives it before your current authorization ends.",
    consequence:
      "File too late and you may face a gap in work authorization while the extension is pending.",
    regulationCite: "8 CFR 214.2(f)(11)(iii)",
    officialUrl: USCIS_STEM,
    applicableVisaTypes: ["OPT", "STEM_OPT"],
    calculate: (p) => stemOptDeadline(p.eadEndDate),
  },
  {
    id: "i20_expiry",
    label: "I-20 expiry",
    description:
      "The program end date on your Form I-20. Keep it valid; request an extension from your DSO before it expires if you need more time.",
    consequence:
      "An expired I-20 without a timely extension is a status violation.",
    regulationCite: "8 CFR 214.2(f)(7)",
    officialUrl: SEVP_REPORTING,
    applicableVisaTypes: ["F-1", "OPT", "STEM_OPT"],
    overrideSourceField: "i20ExpiryDate",
    calculate: (p) => asDate(p.i20ExpiryDate),
  },
  {
    id: "grace_period_end",
    label: "Grace period end",
    description:
      "F-1 students get a 60-day grace period after the program end (or OPT/STEM OPT end) to prepare to depart, transfer, or change status.",
    consequence:
      "Remaining in the US past the grace period without a new status is unlawful presence.",
    regulationCite: "8 CFR 214.2(f)(5)(iv)",
    officialUrl: SEVP_REPORTING,
    applicableVisaTypes: ["F-1", "OPT", "STEM_OPT"],
    overrideSourceField: "gracePeriodEndDate",
    calculate: (p) => {
      if (p.gracePeriodEndDate) return asDate(p.gracePeriodEndDate);
      if (p.visaType === "STEM_OPT") return stemGracePeriodEnd(p.eadEndDate);
      return gracePeriodEnd(p.programEndDate);
    },
  },
  {
    id: "sevp_reporting",
    label: "SEVP reporting deadline",
    description:
      "After a reportable change (employer, address, program, or loss of employment) you must update your DSO/SEVP within 10 days.",
    consequence:
      "Failing to report within 10 days is a status violation that your DSO must record.",
    regulationCite: "8 CFR 214.2(f)(12) & (f)(18)",
    officialUrl: SEVP_REPORTING,
    applicableVisaTypes: ["F-1", "OPT", "STEM_OPT"],
    calculate: (p) => sevpDeadline(p.lastReportableEventDate),
  },
  {
    id: "i94_expiry",
    label: "I-94 expiry",
    description:
      "The admit-until date on your most recent I-94 — the controlling date for how long you may remain in the US in H-1B status.",
    consequence:
      "Staying past the I-94 date without an extension or change of status accrues unlawful presence.",
    regulationCite: "8 CFR 214.1(c)",
    officialUrl: USCIS_H1B,
    applicableVisaTypes: ["H-1B"],
    overrideSourceField: "i94ExpiryDate",
    calculate: (p) => asDate(p.i94ExpiryDate),
  },
  {
    id: "h1b_petition_expiry",
    label: "H-1B petition expiry",
    description:
      "The validity end date on your approved H-1B petition (I-797 approval notice). File an extension before this date to keep working.",
    consequence:
      "Working past the petition validity without a timely extension is unauthorized.",
    regulationCite: "8 CFR 214.2(h)(15)",
    officialUrl: USCIS_H1B,
    applicableVisaTypes: ["H-1B"],
    overrideSourceField: "h1bPetitionExpiry",
    calculate: (p) => asDate(p.h1bPetitionExpiry),
  },
  {
    id: "cap_gap_end",
    label: "Cap-gap coverage end",
    description:
      "If you moved from F-1/OPT to a cap-subject H-1B with an October 1 start, cap-gap extends your status and work authorization until then.",
    consequence:
      "Once cap-gap ends, you must have your H-1B in effect or you fall out of status.",
    regulationCite: "8 CFR 214.2(f)(5)(vi)",
    officialUrl: USCIS_H1B,
    applicableVisaTypes: ["H-1B"],
    overrideSourceField: "capGapEnd",
    calculate: (p) => asDate(p.capGapEnd),
  },
  {
    id: "visa_stamp_expiry",
    label: "Visa stamp expiry",
    description:
      "The expiration of the visa stamp in your passport. You need a valid stamp to re-enter the US after international travel (it does not govern your stay inside the US).",
    consequence:
      "An expired stamp means you must renew at a consulate before returning from abroad.",
    regulationCite: "INA 221; 22 CFR 41.112",
    officialUrl: TRAVEL_DOCS,
    applicableVisaTypes: ["F-1", "OPT", "STEM_OPT", "H-1B", "H-4", "J-1", "Other"],
    overrideSourceField: "visaStampExpiry",
    calculate: (p) => asDate(p.visaStampExpiry),
  },
  {
    id: "passport_expiry",
    label: "Passport expiry",
    description:
      "Your passport generally must be valid at all times while in the US and typically valid 6 months beyond travel. Renew with your home country's consulate.",
    consequence:
      "An expired passport can disrupt travel, visa renewals, and other filings.",
    regulationCite: "8 CFR 214.1(a)(3)",
    officialUrl: TRAVEL_DOCS,
    applicableVisaTypes: ["F-1", "OPT", "STEM_OPT", "H-1B", "H-4", "J-1", "Other"],
    overrideSourceField: "passportExpiry",
    calculate: (p) => asDate(p.passportExpiry),
  },
  {
    id: "renewal_reminder",
    label: "Renewal reminder",
    description:
      "A personal reminder you set for an upcoming renewal or filing you want to track.",
    consequence:
      "This is a self-set reminder; missing it has no direct legal effect but may delay your plans.",
    regulationCite: "",
    officialUrl: "",
    applicableVisaTypes: ["F-1", "OPT", "STEM_OPT", "H-1B", "H-4", "J-1", "Other"],
    overrideSourceField: "nextRenewalReminder",
    calculate: (p) => asDate(p.nextRenewalReminder),
  },
];
